diff --git a/calendar/providers/storage/calStorageUpgrade.sys.mjs b/calendar/providers/storage/calStorageUpgrade.sys.mjs
index bd0c36d1cf8..ef05eac8065 100644
--- a/calendar/providers/storage/calStorageUpgrade.sys.mjs
+++ b/calendar/providers/storage/calStorageUpgrade.sys.mjs
@@ -116,13 +116,13 @@ export function getSql(tblName, tblData, alternateName) {
     const idxOn = idxTbl + "(" + tblData[tblName].join(",") + ")";
     sql = `CREATE INDEX ${altName} ON ${idxOn};`;
   } else {
-    sql = `CREATE TABLE ${altName} (\n`;
+    sql = `CREATE TABLE ${altName} (`;
     for (const [key, type] of Object.entries(tblData[tblName])) {
-      sql += `    ${key} ${type},\n`;
+      sql += `\n    ${key} ${type},`;
     }
   }

-  return sql.replace(/,\s*$/, ");");
+  return sql.replace(/,\s*$/, "\n);");
 }

